Lemma target_block_join : forall m A tbs jnk,
  rw_cells asegs m A [C1 (b8 32)] -> rw_cells asegs m (A + 1) [CB (length tbs) jnk] -> jnk = tbs ->
  rw_cells asegs m A [CB (S (length tbs)) (b8 32 :: tbs)].
Proof.
  intros m A tbs jnk H1 H2 ->.
  assert (H1' : rw_cells asegs m A [CB 1 [b8 32]]) by (eapply rw_cells_reshape; [exact H1 | cbn; split; reflexivity | reflexivity]).
  exact (rw_cells_CB_join asegs _ _ _ _ _ _ H1' H2).
Qed.

